create or replace function public.get_candidate_cbt(p_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.schoolpro_candidate_cbt_attempts;t public.schoolpro_cbt_tests;qs jsonb;saved jsonb;dur int;begin select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token for update;if a.id is null then raise exception 'Invalid examination link';end if;if a.status='submitted' then raise exception 'Examination already submitted';end if;if a.expires_at is not null and now()>a.expires_at then raise exception 'Examination link expired';end if;select * into t from public.schoolpro_cbt_tests where id=a.test_id;if t.id is null then raise exception 'Examination not found';end if;if t.opens_at is not null and now()<t.opens_at then raise exception 'Examination has not opened';end if;if t.closes_at is not null and now()>t.closes_at then raise exception 'Examination has closed';end if;dur:=coalesce(a.duration_minutes,t.duration_minutes,60);if a.started_at is null then update public.schoolpro_candidate_cbt_attempts set started_at=now(),status='in_progress' where id=a.id returning * into a;end if;if now()>a.started_at+make_interval(mins=>dur) then raise exception 'Examination time expired';end if;select coalesce(jsonb_agg(jsonb_build_object('id',q.id,'question_type',q.question_type,'question_text',q.question_text,'options',q.options,'marks',q.marks) order by tq.position),'[]'::jsonb) into qs from public.schoolpro_cbt_test_questions tq join public.schoolpro_question_bank q on q.id=tq.question_id where tq.test_id=t.id;select coalesce(jsonb_object_agg(ans.question_id::text,ans.answer),'{}'::jsonb) into saved from public.schoolpro_candidate_cbt_answers ans where ans.attempt_id=a.id;return jsonb_build_object('attempt_id',a.id,'title',t.title,'instructions',t.instructions,'duration_minutes',dur,'started_at',a.started_at,'questions',qs,'saved_answers',saved);end$$;
create or replace function public.save_candidate_cbt_answer(p_token uuid,p_question uuid,p_answer text) returns void language plpgsql security definer set search_path='' as $$declare a public.schoolpro_candidate_cbt_attempts;t public.schoolpro_cbt_tests;dur int;begin select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token;if a.id is null or a.status='submitted' then raise exception 'Invalid examination attempt';end if;select * into t from public.schoolpro_cbt_tests where id=a.test_id;dur:=coalesce(a.duration_minutes,t.duration_minutes,60);if a.started_at is null or now()>a.started_at+make_interval(mins=>dur) or (a.expires_at is not null and now()>a.expires_at) then raise exception 'Examination expired';end if;if not exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=p_question) then raise exception 'Question is not assigned to this examination';end if;insert into public.schoolpro_candidate_cbt_answers(attempt_id,question_id,answer) values(a.id,p_question,p_answer) on conflict(attempt_id,question_id) do update set answer=excluded.answer;update public.schoolpro_candidate_cbt_attempts set last_saved_at=now() where id=a.id;end$$;
create or replace function public.submit_candidate_cbt(p_token uuid) returns numeric language plpgsql security definer set search_path='' as $$declare a public.schoolpro_candidate_cbt_attempts;s numeric;begin select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token for update;if a.id is null then raise exception 'Invalid examination attempt';end if;if a.status='submitted' then return coalesce(a.score,0);end if;update public.schoolpro_candidate_cbt_answers ans set is_correct=(lower(trim(ans.answer))=lower(trim(q.correct_answer))),marks_awarded=case when lower(trim(ans.answer))=lower(trim(q.correct_answer)) then q.marks else 0 end from public.schoolpro_question_bank q join public.schoolpro_cbt_test_questions tq on tq.question_id=q.id where ans.attempt_id=a.id and ans.question_id=q.id and tq.test_id=a.test_id and q.question_type in('objective','true_false');select coalesce(sum(ans.marks_awarded),0) into s from public.schoolpro_candidate_cbt_answers ans where ans.attempt_id=a.id and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=ans.question_id);update public.schoolpro_candidate_cbt_attempts set status='submitted',submitted_at=now(),score=s,last_saved_at=now() where id=a.id;update public.schoolpro_admissions set entrance_score=s where id=a.application_id;return s;end$$;